import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HeaderComponent } from './components/header/header.component';
import { UploadZoneComponent } from './components/upload-zone/upload-zone.component';
import { ColorCardComponent } from './components/color-card/color-card.component';
import { CandidatePaletteComponent } from './components/candidate-palette/candidate-palette.component';
import { LivePreviewComponent } from './components/live-preview/live-preview.component';
import { ExportModalComponent } from './components/export-modal/export-modal.component';
import { ColorExtractorService } from './services/color-extractor.service';
import { ExtractedPaletteResponse } from './models/palette.model';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    CommonModule,
    HeaderComponent,
    UploadZoneComponent,
    ColorCardComponent,
    CandidatePaletteComponent,
    LivePreviewComponent,
    ExportModalComponent
  ],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent implements OnInit {
  isBackendHealthy: boolean = true;
  isOpenAiConnected: boolean = false;

  // Workflow states
  currentStep: 'upload' | 'analyzing' | 'result' | 'error' = 'upload';
  selectedFile: File | null = null;
  previewImageUrl: string | null = null;
  analysisError: string | null = null;

  // Analysis result
  paletteResult: ExtractedPaletteResponse | null = null;
  isExportModalOpen: boolean = false;

  constructor(public colorService: ColorExtractorService) {}

  ngOnInit() {
    this.checkHealth();
  }

  checkHealth() {
    this.colorService.checkBackendHealth().subscribe({
      next: (res) => {
        this.isBackendHealthy = true;
        this.isOpenAiConnected = res.openai_configured;
      },
      error: () => {
        this.isBackendHealthy = false;
      }
    });
  }

  onFileSelected(file: File) {
    this.selectedFile = file;
    this.analysisError = null;

    // Create local object URL for preview
    if (this.previewImageUrl) {
      URL.revokeObjectURL(this.previewImageUrl);
    }
    this.previewImageUrl = URL.createObjectURL(file);

    this.startAnalysis(file);
  }

  startAnalysis(file: File) {
    this.currentStep = 'analyzing';

    this.colorService.analyzeLogo(file).subscribe({
      next: (response) => {
        this.paletteResult = response;
        this.currentStep = 'result';
        this.colorService.showToast('Brand colors successfully extracted!', 'success');
      },
      error: (err: Error) => {
        this.analysisError = err.message || 'Failed to extract colors from image.';
        this.currentStep = 'error';
        this.colorService.showToast(this.analysisError, 'error');
      }
    });
  }

  retryUpload() {
    if (this.selectedFile) {
      this.startAnalysis(this.selectedFile);
    } else {
      this.resetAnalysis();
    }
  }

  resetAnalysis() {
    this.currentStep = 'upload';
    this.paletteResult = null;
    this.analysisError = null;
    this.selectedFile = null;
    if (this.previewImageUrl) {
      URL.revokeObjectURL(this.previewImageUrl);
      this.previewImageUrl = null;
    }
  }

  copyAllColors() {
    if (!this.paletteResult) return;
    const p = this.paletteResult;
    const text = `PRIMARY: ${p.primary.hex} (${p.primary.name})
SECONDARY: ${p.secondary.hex} (${p.secondary.name})
ACCENT: ${p.accent.hex} (${p.accent.name})`;

    this.colorService.copyToClipboard(text, 'All 3 Brand Colors');
  }

  openExportModal() {
    this.isExportModalOpen = true;
  }

  closeExportModal() {
    this.isExportModalOpen = false;
  }
}
<div class="app-layout">
  <!-- Top Navigation Header -->
  <app-header 
    [isBackendHealthy]="isBackendHealthy" 
    [isOpenAiConnected]="isOpenAiConnected"
  ></app-header>

  <main class="main-content">
    <div class="content-container">

      <!-- 1. Initial State: Upload Zone -->
      <div *ngIf="currentStep === 'upload'" class="view-wrapper animate-fade-in">
        <app-upload-zone 
          [isAnalyzing]="false" 
          (fileSelected)="onFileSelected($event)"
        ></app-upload-zone>
      </div>

      <!-- 2. Loading State: Analyzing Logo -->
      <div *ngIf="currentStep === 'analyzing'" class="view-wrapper animate-fade-in">
        <div class="analyzing-card glass-panel">
          <div class="preview-thumbnail-wrap">
            <img *ngIf="previewImageUrl" [src]="previewImageUrl" alt="Uploaded Logo" class="preview-thumbnail-img" />
            <div class="scan-line"></div>
          </div>

          <div class="analyzing-text-wrap">
            <h2 class="analyzing-title">Analyzing your logo...</h2>
            <p class="analyzing-desc">
              Filtering transparency, performing K-Means color clustering, and evaluating semantic brand roles with AI.
            </p>
          </div>

          <!-- Loading Visualizer -->
          <div class="loading-bars-container">
            <div class="bar bar-1"></div>
            <div class="bar bar-2"></div>
            <div class="bar bar-3"></div>
            <div class="bar bar-4"></div>
            <div class="bar bar-5"></div>
          </div>

          <div class="step-chips">
            <span class="step-chip done">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" width="12" height="12"><polyline points="20 6 9 17 4 12"/></svg>
              Transparency Isolated
            </span>
            <span class="step-chip active">
              <span class="spinner-dot"></span>
              Color Space Clustering
            </span>
            <span class="step-chip pending">
              Semantic AI Evaluation
            </span>
          </div>
        </div>
      </div>

      <!-- 3. Error State -->
      <div *ngIf="currentStep === 'error'" class="view-wrapper animate-fade-in">
        <div class="error-card glass-panel">
          <div class="error-icon-wrap">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="36" height="36">
              <circle cx="12" cy="12" r="10"/>
              <line x1="12" y1="8" x2="12" y2="12"/>
              <line x1="12" y1="16" x2="12.01" y2="16"/>
            </svg>
          </div>
          <h3 class="error-title">Analysis Failed</h3>
          <p class="error-detail">{{ analysisError }}</p>

          <div class="error-actions">
            <button type="button" class="btn-primary" (click)="retryUpload()">Try Again</button>
            <button type="button" class="btn-secondary" (click)="resetAnalysis()">Choose Another Logo</button>
          </div>
        </div>
      </div>

      <!-- 4. Result State: Palette Display -->
      <div *ngIf="currentStep === 'result' && paletteResult" class="view-wrapper animate-fade-in">
        <!-- Result Bar & Meta -->
        <div class="result-top-bar glass-panel">
          <div class="logo-meta-info">
            <div class="logo-thumb-small">
              <img *ngIf="previewImageUrl" [src]="previewImageUrl" alt="Logo preview" />
            </div>
            <div class="meta-texts">
              <h3 class="meta-filename">{{ paletteResult.image_metadata?.filename || 'Uploaded Logo' }}</h3>
              <div class="meta-tags">
                <span class="meta-tag">{{ paletteResult.image_metadata?.width }}x{{ paletteResult.image_metadata?.height }} px</span>
                <span *ngIf="paletteResult.image_metadata?.has_alpha" class="meta-tag alpha-tag">
                  {{ paletteResult.image_metadata?.filtered_transparent_percentage }}% Background Filtered
                </span>
                <span class="meta-tag ai-tag" [class.openai]="paletteResult.ai_selection_source === 'openai'">
                  {{ paletteResult.ai_selection_source === 'openai' ? 'OpenAI GPT-4o Selected' : 'Color Theory Selected' }}
                </span>
              </div>
            </div>
          </div>

          <div class="result-actions">
            <button type="button" class="btn-action btn-copy-all" (click)="copyAllColors()">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16">
                <rect x="9" y="9" width="13" height="13" rx="2" ry="2"/>
                <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>
              </svg>
              <span>Copy All Colors</span>
            </button>

            <button type="button" class="btn-action btn-export" (click)="openExportModal()">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16">
                <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
                <polyline points="7 10 12 15 17 10"/>
                <line x1="12" y1="15" x2="12" y2="3"/>
              </svg>
              <span>Export Palette</span>
            </button>

            <button type="button" class="btn-action btn-new" (click)="resetAnalysis()">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16">
                <line x1="12" y1="5" x2="12" y2="19"/>
                <line x1="5" y1="12" x2="19" y2="12"/>
              </svg>
              <span>New Logo</span>
            </button>
          </div>
        </div>

        <!-- AI Summary Quote -->
        <div *ngIf="paletteResult.ai_summary" class="ai-summary-card glass-panel">
          <div class="summary-sparkle">
            <svg viewBox="0 0 24 24" fill="currentColor" width="18" height="18">
              <path d="M12 2L14.4 9.6L22 12L14.4 14.4L12 22L9.6 14.4L2 12L9.6 9.6L12 2Z"/>
            </svg>
          </div>
          <p class="summary-text">{{ paletteResult.ai_summary }}</p>
        </div>

        <!-- Three Main Color Cards -->
        <div class="color-cards-grid">
          <!-- PRIMARY -->
          <app-color-card
            [color]="paletteResult.primary"
            roleTitle="PRIMARY"
            roleType="primary"
          ></app-color-card>

          <!-- SECONDARY -->
          <app-color-card
            [color]="paletteResult.secondary"
            roleTitle="SECONDARY"
            roleType="secondary"
          ></app-color-card>

          <!-- ACCENT -->
          <app-color-card
            [color]="paletteResult.accent"
            roleTitle="ACCENT"
            roleType="accent"
          ></app-color-card>
        </div>

        <!-- Clustered Candidate Spectrum -->
        <app-candidate-palette
          *ngIf="paletteResult.candidates.length > 0"
          [candidates]="paletteResult.candidates"
          [totalCandidates]="paletteResult.total_candidates"
        ></app-candidate-palette>

        <!-- Live UI Mockup Simulation -->
        <app-live-preview
          [primary]="paletteResult.primary"
          [secondary]="paletteResult.secondary"
          [accent]="paletteResult.accent"
        ></app-live-preview>
      </div>

    </div>
  </main>

  <!-- Export Palette Modal -->
  <app-export-modal
    *ngIf="isExportModalOpen && paletteResult"
    [palette]="paletteResult"
    (close)="closeExportModal()"
  ></app-export-modal>

  <!-- Toast Notification System -->
  <div class="toast-container">
    <div 
      *ngFor="let toast of colorService.toasts()" 
      class="toast" 
      [ngClass]="toast.type"
    >
      <span>{{ toast.text }}</span>
    </div>
  </div>
</div>
